/**
 * Transfers values from editors to FieldValueHosts when using Server Page HTML generated by the server.
 * 
 * @module jivs-dom/Editors/ConcreteClasses/ServerPageValuesReader
 */

import { ReaderOptions } from '@plblum/jivs-engine/build/Interfaces/ReaderAndWriter';
import { IValueHostsManager } from '@plblum/jivs-engine/build/Interfaces/ValueHostsManager';
import { EditorReader } from './EditorReader';

/**
 * Transfers values from editors to FieldValueHosts after the server has regenerated the whole page,
 * then draws the resulting validation state in the UI.
 *
 * Use it in a Server Page round trip:
 * 1. Before submitting, the app saved vhm.getCapturedState() in a hidden input.
 *    The server returned that string unchanged with the regenerated HTML.
 * 2. The browser built a new ValueHostsManager using that string as config.capturedState.
 *    Each FieldValueHost now has the validation state it had before the submit,
 *    but restoring state does not call any callbacks, so nothing is drawn yet.
 * 3. FormInstaller.install() collected the new elements and attached the dispatchers.
 *    Fields without an editor are disabled.
 * 4. ServerPageValuesReader.read() brings the FieldValueHosts in line with the new HTML.
 *
 * read() does this:
 * - Every editor's value is transferred with setTextValue, using the same options as EditorReader.
 *   The server may have kept, revised, added or removed any editor, so unlike an EditorReader
 *   after a DOM update, no filter such as onlyReplacedEditors is used.
 * - Fields whose text is unchanged are skipped (skipIfUnchanged), so they keep the state
 *   they had in capturedState, including any issues found.
 * - Fields whose text changed, or that became enabled, are reset to NotAttempted (reset).
 *   Their old issues no longer describe the new value.
 * - Preliminary validation runs (ReaderOptions.preliminaryValidation, default true).
 *   It only considers fields that are NotAttempted or NeedsValidation, which are the reset ones.
 * - broadcastState(true, false) sends the validation state of every enabled FieldValueHost, and the form,
 *   to the presentation handlers, error displays and validation summary.
 *   That is what makes restored issues visible. Text values are not broadcast because the editors
 *   are the source of the values and must not be overwritten.
 *
 * Setting preliminaryValidation to false skips both the validation and the broadcast.
 *
 * On a page that has no captured state, every field starts as NotAttempted, so the
 * broadcast reflects only the preliminary validation of the values read.
 *
 * Use EditorReader instead when the ValueHostsManager and DOM survive and only some editors are replaced
 * (see Form Reinstallation after DOM has changed).
 *
 * Options sent to FieldValueHost.setTextValue, inherited from EditorReader:
 * - skipIfUnchanged = true
 * - skipValueChangedCallback = true
 * - disableFormatter = true (we may change this to allow reformatTextValue. TBD)
 * - validate = false
 * - reset = true
 */
export class ServerPageValuesReader extends EditorReader
{
    /**
     * Creates an instance of the ServerPageValuesReader.
     * @param valueHostsManager - The manager for the ValueHosts.
     * @param options - The reader options.
     */
    constructor(valueHostsManager: IValueHostsManager, options?: ReaderOptions)
    {
        super(valueHostsManager, options);
    }

    public override read(): void
    {
        super.read();
        if (this.options?.preliminaryValidation !== false)
            this.valueHostsManager.broadcastState(true, false); // reflect validation state in the UI but no changes to editors which are the source of the values
    }

}    